package build

import (
	"archive/tar"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"html"
	"io"
	"os"
	"path/filepath"
)

// CIM operating system ids (DMTF CIM_OperatingSystem.OsType).
var cimOS = map[string]int{"ubuntu64Guest": 94, "debian10_64Guest": 96, "debian11_64Guest": 96, "debian12_64Guest": 96}

const ovfTemplate = `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by osb -->
<Envelope xmlns="http://schemas.dmtf.org/ovf/envelope/1" xmlns:cim="http://schemas.dmtf.org/wbem/wscim/1/common" xmlns:ovf="http://schemas.dmtf.org/ovf/envelope/1" xmlns:rasd="http://schemas.dmtf.org/wbem/wscim/1/cim-schema/2/CIM_ResourceAllocationSettingData" xmlns:vmw="http://www.vmware.com/schema/ovf" xmlns:vssd="http://schemas.dmtf.org/wbem/wscim/1/cim-schema/2/CIM_VirtualSystemSettingData" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
  <References>
    <File ovf:href="%[1]s" ovf:id="file1" ovf:size="%[2]d"/>
  </References>
  <DiskSection>
    <Info>Virtual disk information</Info>
    <Disk ovf:capacity="%[3]d" ovf:capacityAllocationUnits="byte" ovf:diskId="vmdisk1" ovf:fileRef="file1" ovf:format="http://www.vmware.com/interfaces/specifications/vmdk.html#streamOptimized" ovf:populatedSize="%[2]d"/>
  </DiskSection>
  <NetworkSection>
    <Info>The list of logical networks</Info>
    <Network ovf:name="nat">
      <Description>The nat network</Description>
    </Network>
  </NetworkSection>
  <VirtualSystem ovf:id="%[4]s">
    <Info>A virtual machine</Info>
    <Name>%[4]s</Name>
    <OperatingSystemSection ovf:id="%[5]d" vmw:osType="%[6]s">
      <Info>The kind of installed guest operating system</Info>
    </OperatingSystemSection>
    <VirtualHardwareSection>
      <Info>Virtual hardware requirements</Info>
      <System>
        <vssd:ElementName>Virtual Hardware Family</vssd:ElementName>
        <vssd:InstanceID>0</vssd:InstanceID>
        <vssd:VirtualSystemIdentifier>%[4]s</vssd:VirtualSystemIdentifier>
        <vssd:VirtualSystemType>vmx-14</vssd:VirtualSystemType>
      </System>
      <Item>
        <rasd:AllocationUnits>hertz * 10^6</rasd:AllocationUnits>
        <rasd:Description>Number of Virtual CPUs</rasd:Description>
        <rasd:ElementName>%[7]d virtual CPU(s)</rasd:ElementName>
        <rasd:InstanceID>1</rasd:InstanceID>
        <rasd:ResourceType>3</rasd:ResourceType>
        <rasd:VirtualQuantity>%[7]d</rasd:VirtualQuantity>
      </Item>
      <Item>
        <rasd:AllocationUnits>byte * 2^20</rasd:AllocationUnits>
        <rasd:Description>Memory Size</rasd:Description>
        <rasd:ElementName>%[8]dMB of memory</rasd:ElementName>
        <rasd:InstanceID>2</rasd:InstanceID>
        <rasd:ResourceType>4</rasd:ResourceType>
        <rasd:VirtualQuantity>%[8]d</rasd:VirtualQuantity>
      </Item>
      <Item>
        <rasd:Address>0</rasd:Address>
        <rasd:Description>SATA Controller</rasd:Description>
        <rasd:ElementName>sataController0</rasd:ElementName>
        <rasd:InstanceID>3</rasd:InstanceID>
        <rasd:ResourceSubType>vmware.sata.ahci</rasd:ResourceSubType>
        <rasd:ResourceType>20</rasd:ResourceType>
      </Item>
      <Item>
        <rasd:AddressOnParent>0</rasd:AddressOnParent>
        <rasd:ElementName>disk0</rasd:ElementName>
        <rasd:HostResource>ovf:/disk/vmdisk1</rasd:HostResource>
        <rasd:InstanceID>4</rasd:InstanceID>
        <rasd:Parent>3</rasd:Parent>
        <rasd:ResourceType>17</rasd:ResourceType>
      </Item>
      <Item>
        <rasd:AddressOnParent>2</rasd:AddressOnParent>
        <rasd:AutomaticAllocation>true</rasd:AutomaticAllocation>
        <rasd:Connection>nat</rasd:Connection>
        <rasd:Description>E1000 ethernet adapter on "nat"</rasd:Description>
        <rasd:ElementName>ethernet0</rasd:ElementName>
        <rasd:InstanceID>5</rasd:InstanceID>
        <rasd:ResourceSubType>E1000</rasd:ResourceSubType>
        <rasd:ResourceType>10</rasd:ResourceType>
      </Item>
    </VirtualHardwareSection>
  </VirtualSystem>
</Envelope>
`

// OVA builds a qcow2 image and packages it as an OVA appliance.
func OVA(c *Context) (*Output, error) {
	work := filepath.Join(c.OutDir, ".ova")
	if err := os.MkdirAll(work, 0o755); err != nil {
		return nil, err
	}
	if !c.KeepWorkDir {
		defer os.RemoveAll(work)
	}
	qcow, err := c.buildQCOW2(filepath.Join(work, c.baseName()+".qcow2"), false)
	if err != nil {
		return nil, err
	}
	settings := c.Plan.Artifact("ova")
	vmdkName := c.baseName() + "-disk1.vmdk"
	vmdk := filepath.Join(work, vmdkName)
	c.log("converting to streamOptimized VMDK")
	if err := c.run("qemu-img", "convert", "-O", "vmdk", "-o", "subformat=streamOptimized", qcow, vmdk); err != nil {
		return nil, err
	}
	_, capacity, err := imageFormat(qcow)
	if err != nil {
		return nil, err
	}
	st, err := os.Stat(vmdk)
	if err != nil {
		return nil, err
	}
	cpus, err := intSetting(settings, "cpus", 2)
	if err != nil {
		return nil, err
	}
	mem, err := intSetting(settings, "memory", 2048)
	if err != nil {
		return nil, err
	}
	osType := setting(settings, "os-type", c.Plan.Flavor.OVAOSType)
	cim, ok := cimOS[osType]
	if !ok {
		cim = 101 // Other Linux 64-bit
	}
	name := setting(settings, "name", c.baseName())
	ovf := fmt.Sprintf(ovfTemplate, html.EscapeString(vmdkName), st.Size(), capacity, html.EscapeString(name), cim, html.EscapeString(osType), cpus, mem)
	ovfName := c.baseName() + ".ovf"
	ovfPath := filepath.Join(work, ovfName)
	if err := os.WriteFile(ovfPath, []byte(ovf), 0o644); err != nil {
		return nil, err
	}
	var mf string
	for _, f := range []string{ovfName, vmdkName} {
		sum, err := sha256File(filepath.Join(work, f))
		if err != nil {
			return nil, err
		}
		mf += fmt.Sprintf("SHA256(%s)= %s\n", f, sum)
	}
	mfName := c.baseName() + ".mf"
	if err := os.WriteFile(filepath.Join(work, mfName), []byte(mf), 0o644); err != nil {
		return nil, err
	}
	dest := filepath.Join(c.OutDir, c.baseName()+".ova")
	c.log("writing %s", dest)
	// The OVF descriptor must be the first file in the archive.
	if err := writeTar(dest, work, []string{ovfName, vmdkName, mfName}); err != nil {
		return nil, err
	}
	return &Output{Files: []string{dest}}, nil
}

func sha256File(p string) (string, error) {
	f, err := os.Open(p)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func writeTar(dest, dir string, names []string) error {
	out, err := os.Create(dest + ".part")
	if err != nil {
		return err
	}
	defer out.Close()
	tw := tar.NewWriter(out)
	for _, n := range names {
		p := filepath.Join(dir, n)
		st, err := os.Stat(p)
		if err != nil {
			return err
		}
		hdr := &tar.Header{Name: n, Mode: 0o644, Size: st.Size(), ModTime: st.ModTime(), Format: tar.FormatUSTAR, Uname: "someone", Gname: "someone"}
		if err := tw.WriteHeader(hdr); err != nil {
			return err
		}
		f, err := os.Open(p)
		if err != nil {
			return err
		}
		_, err = io.Copy(tw, f)
		f.Close()
		if err != nil {
			return err
		}
	}
	if err := tw.Close(); err != nil {
		return err
	}
	if err := out.Close(); err != nil {
		return err
	}
	return os.Rename(dest+".part", dest)
}
